-- Generated by Rowlit from PostgreSQL. Parameters (:name) are prompted for when you run a statement.

-- ISO countries
-- public.countries: UPDATE
UPDATE public.countries
SET
    name = :name,
    iso_code = :iso_code
WHERE id = :id;

-- People who buy things
-- public.customers: UPDATE
UPDATE public.customers
SET
    name = :name,
    email = :email,
    country_id = :country_id,
    is_active = :is_active,
    created_at = :created_at,
    profile = :profile,
    tags = :tags
WHERE id = :id;

-- public.products: UPDATE
UPDATE public.products
SET
    sku = :sku,
    name = :name,
    price = :price,
    stock = :stock,
    attributes = :attributes,
    thumbnail = :thumbnail
WHERE id = :id;

-- public.orders: UPDATE
UPDATE public.orders
SET
    customer_id = :customer_id,
    order_date = :order_date,
    status = :status,
    total = :total,
    note = :note
WHERE id = :id;

-- public.order_lines: UPDATE
UPDATE public.order_lines
SET
    product_id = :product_id,
    qty = :qty,
    unit_price = :unit_price
WHERE order_id = :order_id
  AND line_no = :line_no;

-- One column per PostgreSQL type family
