    ratio = :ratio,
    score = :score,
    price = :price,
    code = :code,
    day = :day,
    at_local = :at_local,
    opens = :opens,
    opens_tz = :opens_tz,
    wait = :wait,
    doc = :doc,
    spec = :spec,
    ip = :ip,
    mac = :mac,
    location = :location,
    search = :search,
    during = :during,
    counts = :counts,
    statuses = :statuses,
    "user" = :user,
    "CamelCase" = :CamelCase
WHERE id = :id;

-- Issued invoices
-- sales.invoices: UPDATE
UPDATE sales.invoices
SET
    customer_id = :customer_id,
    issued_at = :issued_at,
    amount = :amount,
    paid = :paid,
    pdf = :pdf
WHERE invoice_id = :invoice_id;
